describe('Protected Page Authentication Redirect', () => {
  const protectedUrl = '/dashboard';
  const loginUrl = '/login';
  const baseUrl = Cypress.config('baseUrl');

  beforeEach(() => {
    cy.clearCookies();
    cy.clearLocalStorage();
    cy.window().then((win) => {
      win.sessionStorage.clear();
    });
  });

  it('should redirect unauthenticated user to login when accessing protected page', () => {
    cy.visit(protectedUrl, { failOnStatusCode: false });

    cy.url().should('include', loginUrl);
    cy.get('[data-testid="login-form"]').should('be.visible');
    cy.get('h1').should('contain', 'Login');
  });

  it('should redirect to login and preserve redirect URL for post-login navigation', () => {
    cy.visit(protectedUrl, { failOnStatusCode: false });

    cy.url().should('include', loginUrl);
    cy.url().then((url) => {
      expect(url).to.include('redirect');
    });

    cy.get('[data-testid="email-input"]').type('testuser@example.com');
    cy.get('[data-testid="password-input"]').type('ValidPassword123!');
    cy.get('[data-testid="login-button"]').click();

    cy.url().should('include', protectedUrl);
    cy.get('[data-testid="dashboard-content"]').should('be.visible');
  });

  it('should handle multiple protected page redirects consistently', () => {
    const protectedPages = ['/dashboard', '/profile', '/settings'];

    protectedPages.forEach((page) => {
      cy.clearCookies();
      cy.clearLocalStorage();
      cy.window().then((win) => {
        win.sessionStorage.clear();
      });

      cy.visit(page, { failOnStatusCode: false });
      cy.url().should('include', loginUrl);
      cy.get('[data-testid="login-form"]').should('be.visible');
    });
  });

  it('should not redirect authenticated user from protected page', () => {
    cy.login('testuser@example.com', 'ValidPassword123!');

    cy.visit(protectedUrl);

    cy.url().should('include', protectedUrl);
    cy.url().should('not.include', loginUrl);
    cy.get('[data-testid="dashboard-content"]').should('be.visible');
  });

  it('should handle expired session and redirect to login', () => {
    cy.login('testuser@example.com', 'ValidPassword123!');
    cy.visit(protectedUrl);
    cy.get('[data-testid="dashboard-content"]').should('be.visible');

    cy.clearCookies();
    cy.reload();

    cy.url().should('include', loginUrl);
    cy.get('[data-testid="login-form"]').should('be.visible');
  });

  it('should handle direct API calls without authentication token', () => {
    cy.request({
      method: 'GET',
      url: `${baseUrl}/api/protected-resource`,
      failOnStatusCode: false
    }).then((response) => {
      expect(response.status).to.equal(401);
    });
  });

  it('should redirect on protected page with invalid token', () => {
    cy.setCookie('authToken', 'invalid.token.here');

    cy.visit(protectedUrl, { failOnStatusCode: false });

    cy.url().should('include', loginUrl);
    cy.get('[data-testid="login-form"]').should('be.visible');
  });
});
